    const {socket} = await connectSocket(baseUrl);

    const bareFrames = await sendAndDrain(socket, [{type: 'list_conversations'}, {type: 'ping', timestamp: 1}]);
    const malformedCases = {
      limitZero: {type: 'list_conversations', limit: 0},
      limitOver: {type: 'list_conversations', limit: 201},
      limitFloat: {type: 'list_conversations', limit: 1.5},
