    };

    const outcomes: Record<string, {types: string[]; code?: string; namesLimit: boolean; namesBefore: boolean}> = {};
    for (const [name, payload] of Object.entries(malformedCases)) {
      const frames = await sendAndDrain(socket, [payload, {type: 'ping', timestamp: 2}]);
      const message = String(frames[0]?.message ?? '');
      outcomes[name] = {
        types: frames.map(frame => frame.type),
        code: frames[0]?.code,
        namesLimit: message.includes('limit'),
        namesBefore: message.includes('before'),
      };
    }

    expect({
      bareTypes: bareFrames.map(frame => frame.type),
      outcomes,
