        limitFloat: {types: ['error', 'pong'], code: 'INVALID_MESSAGE', namesLimit: true, namesBefore: false},
        limitString: {types: ['error', 'pong'], code: 'INVALID_MESSAGE', namesLimit: true, namesBefore: false},
        beforeString: {types: ['error', 'pong'], code: 'INVALID_MESSAGE', namesLimit: false, namesBefore: true},
        beforeOnlyUpdatedAt: {types: ['error', 'pong'], code: 'INVALID_MESSAGE', namesLimit: false, namesBefore: true},
        beforeOnlySessionId: {types: ['error', 'pong'], code: 'INVALID_MESSAGE', namesLimit: false, namesBefore: true},
        beforeBadDate: {types: ['error', 'pong'], code: 'INVALID_MESSAGE', namesLimit: false, namesBefore: true},
      },
    });
