  it('answers list_conversations before stream_end while a user_message turn is streaming on the same session', async () => {
    const turnEntered = createGate();
    const releaseTurn = createGate();
    const {baseUrl} = await startAcceptanceEngine({
      sessionStore: new InMemorySessionStore(),
      history: {enabled: true},
      beforeModelResponse: async () => {
        turnEntered.release();
        await releaseTurn.until;
        return 'system';
      },
    });

    const {socket} = await connectSocket(baseUrl);
    socket.send(JSON.stringify({type: 'user_message', content: 'hold'}));
    await turnEntered.until;

    const seenBeforeRelease: string[] = [];
    const listReply = new Promise<WireFrame>(resolve => {
      const onMessage = (raw: Buffer | string) => {
        const frame = JSON.parse(String(raw)) as WireFrame;
        seenBeforeRelease.push(frame.type);
        if (frame.type === 'conversation_list' || frame.type === 'error') {
          socket.off('message', onMessage);
          resolve(frame);
        }
      };
      socket.on('message', onMessage);
    });
    socket.send(JSON.stringify({type: 'list_conversations'}));
    const reply = await listReply;

    const streamEndPromise = waitForType(socket, 'stream_end');
    releaseTurn.release();
    const ended = await streamEndPromise;

    expect({
      replyType: reply.type,
      sawStreamEndBeforeReply: seenBeforeRelease.includes('stream_end'),
      endedType: ended.type,
    }).toEqual({
      replyType: 'conversation_list',
      sawStreamEndBeforeReply: false,
      endedType: 'stream_end',
    });
  });
