interface AcceptanceEngineOptions {
  sessionStore: SessionStore;
  resume?: {enabled: boolean; latest?: boolean};
  history?: {enabled: boolean};
  beforeModelResponse?: () => Promise<string>;
}

async function startAcceptanceEngine(options: AcceptanceEngineOptions): Promise<{baseUrl: string}> {
  const wsAuth: WsAuthenticator = async () => ({id: 'u1'});
  const transport = {
    port: 0,
    ...(options.resume ? {resume: options.resume} : {}),
    ...(options.history ? {history: options.history} : {}),
  };
  const orchestrator = options.beforeModelResponse
    ? {hooks: {beforeModelResponse: options.beforeModelResponse}}
    : undefined;
  const config = {
    provider: {type: 'mock' as const},
    prompt: {identity: 'Acceptance test.'},
    session: options.sessionStore,
    auth: {ws: wsAuth},
    transport,
    ...(orchestrator ? {orchestrator} : {}),
  };
  const engine = createHalEngine(config);
  await engine.start();
  engines.push(engine);
  const address = engine.server.address();
  const port = typeof address === 'object' && address !== null ? address.port : 0;
  return {baseUrl: `ws://127.0.0.1:${port}/hal/ws`};
}

function seedConversation(
  store: InMemorySessionStore,
  sessionId: string,
  userId: string,
  timestamp: string,
  content: string
): void {
  const session = store.create(sessionId, userId, {authHeaders: {authorization: 'Bearer stored-secret'}});
  session.entries.push({role: 'user', content, timestamp});
}

function recordingListStore(inner: InMemorySessionStore, recorded: RecordedListCall[]): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
    lookup: sessionId => inner.lookup(sessionId),
    latestFor: userId => inner.latestFor(userId),
    listFor: (userId, options) => {
      recorded.push({userId, limit: options?.limit, before: options?.before});
      return inner.listFor(userId, options);
    },
  };
}

function rejectingListStore(inner: InMemorySessionStore, message: string): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
    listFor: () => Promise.reject(new Error(message)),
  };
}

function connectSocket(url: string): Promise<{socket: WebSocket; connected: WireFrame}> {
  return new Promise((resolve, reject) => {
    const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
    sockets.push(socket);
    let settled = false;
    socket.on('error', error => {
      if (!settled) reject(error);
    });
    const onMessage = (raw: Buffer | string) => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      if (frame.type !== 'connected') return;
      settled = true;
      socket.off('message', onMessage);
      resolve({socket, connected: frame});
    };
    socket.on('message', onMessage);
  });
}

function sendAndDrain(socket: WebSocket, payloads: unknown[]): Promise<WireFrame[]> {
  return new Promise(resolve => {
    const collected: WireFrame[] = [];
    const onMessage = (raw: Buffer | string) => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      collected.push(frame);
      if (frame.type === 'pong') {
        socket.off('message', onMessage);
        resolve(collected);
      }
    };
    socket.on('message', onMessage);
    for (const payload of payloads) socket.send(JSON.stringify(payload));
  });
}

function connectAndSettle(url: string): Promise<WireFrame[]> {
  return new Promise((resolve, reject) => {
    const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
    sockets.push(socket);
    const frames: WireFrame[] = [];
    socket.on('error', reject);
    socket.on('message', raw => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      frames.push(frame);
      if (frame.type === 'connected') socket.send(JSON.stringify({type: 'ping', timestamp: 1}));
      if (frame.type === 'pong') resolve(frames);
    });
  });
}

function waitForType(socket: WebSocket, targetType: string): Promise<WireFrame> {
  return new Promise(resolve => {
    const onMessage = (raw: Buffer | string) => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      if (frame.type !== targetType) return;
      socket.off('message', onMessage);
      resolve(frame);
    };
    socket.on('message', onMessage);
  });
}

function createGate(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release: () => release()};
}

